 dict(slug='hec-attestation',symbol='HEC',title='Degree Attestation Assistance',desc='Understand HEC degree attestation requirements, submission options and the identity details that must match before you apply.',summary='Understand HEC requirements, submission options and common degree-related issues.',audience='Graduates preparing a university degree or transcript for international use.',answer='Start with the qualification, issuing institution and academic record. HEC determines whether a higher-education document is eligible for its attestation service.',steps=['Identify the qualification, awarding institution and campus.','Compare the degree, transcript, CNIC and passport details before applying.','Use HEC’s current official application instructions and resolve any queries.','Confirm any further authentication with the organisation receiving your document.'],check='An attestation is not an equivalence decision or a promise of acceptance by an employer. Submission formats and verification arrangements must be checked on the current HEC portal.',sources=['hec','nadra'],related=['/documents/degree/','/problems/degree-passport-name-mismatch/','/guides/hec-vs-ibcc/']),
 dict(slug='ibcc-attestation',symbol='IBCC',title='IBCC Attestation Assistance',desc='Find the right starting point for school certificates, diplomas and board-issued records, and check whether IBCC or another authority applies.',summary='Find the right starting point for school certificates, diplomas and board-issued records.',audience='Applicants with school-level qualifications or a diploma whose attesting authority needs to be identified.',answer='The awarding body and qualification level matter. Check IBCC’s scope before treating a diploma or school certificate as a university qualification.',steps=['Identify the board or awarding body and the exact certificate title.','Ask the issuer about verification and correction of record differences.','Confirm IBCC eligibility, prerequisites and the permitted submission route.','Check destination requirements after the educational stage.'],check='Not every document called a diploma follows the same route. Technical and vocational certificates may involve a different competent authority.',sources=['ibcc','navttc'],related=['/documents/education/','/guides/hec-vs-ibcc/','/navttc/']),
 dict(slug='mofa-attestation',symbol='MOFA',title='MOFA Attestation Assistance',desc='Understand document-specific prerequisites, permitted submission arrangements and the questions to confirm before the foreign affairs stage.',summary='Understand document-specific prerequisites before the foreign affairs stage.',audience='People preparing Pakistani documents for a receiving organisation abroad.',answer='Check the document category and prerequisite signatures before approaching MOFA. Do not assume that every document can be submitted in the same way.',steps=['Identify the original issuer and any prior authority stage.','Check the latest MOFA instructions for this document category.','Confirm identity, representation and appearance requirements.','Confirm whether the destination needs an apostille or another legalization route.'],check='Fees, appointment arrangements, courier eligibility and personal appearance rules can change. Confirm them directly before payment or travel.',sources=['mofa'],related=['/guides/mofa-attestation-pakistan/','/services/apostille/','/services/embassy-legalization/']),
 dict(slug='apostille',symbol='A /',title='Apostille Assistance',desc='Check whether the Apostille Convention route applies to your document, your destination and the organisation receiving it.',summary='Check whether the Convention route applies to your document and destination.',audience='Applicants whose receiving organisation requests an apostille on a Pakistani public document.',answer='An apostille route depends on the Convention being applicable between the relevant states, the document being within its scope and the receiving organisation’s requirements. Country membership alone is not the complete check.',steps=['Obtain the receiving organisation’s written instructions.','Check the HCCH status table, entry into force and relevant declarations or objections.','Confirm the document category and prerequisites with the competent authority.','Check translation and recognition requirements separately.'],check='An apostille authenticates origin; it does not establish that a qualification will be recognised or that the document’s contents will be accepted.',sources=['hcch','mofa'],related=['/guides/apostille-vs-embassy-attestation/','/countries/','/services/mofa-attestation/']),
