GUIDES = [
 dict(slug='degree-name-different-from-passport',title='Degree name different from passport?',category='Document problems',summary='Identify which record needs attention before starting attestation.',desc='A degree, passport or CNIC that shows a different spelling or a missing surname needs the right issuer, not another stamp. Compare the records first.',answer='Compare the degree, passport and identity record. Ask the institution responsible for the incorrect record about its correction process. Do not edit the document yourself or assume an affidavit will be accepted.',sections=[('Why the distinction matters','A missing surname, transliteration difference or changed name may need a different response. The spelling that appears most often is not, by itself, proof that a record is correct.'),('Which issuer handles which record','<table class="content-table"><thead><tr><th>Record showing the difference</th><th>Who can correct or verify it</th></tr></thead><tbody><tr><td>Degree or transcript</td><td>The university or board that issued the academic record</td></tr><tr><td>Passport</td><td>DGIP, through its passport service</td></tr><tr><td>CNIC, B-form or identity record</td><td>NADRA</td></tr><tr><td>Marriage or name-change record</td><td>The civil registration or issuing authority</td></tr></tbody></table>'),('A practical sequence','Record the exact difference. Identify the issuer of each document. Ask the receiving institution what evidence it will accept. Then obtain written correction or verification instructions from the relevant issuer.'),('Documents to have available','Keep your degree, transcript, passport, identity record and the receiving organisation’s request available for your own comparison. At the first enquiry, describe the difference without sending document numbers or scans.'),('Common problems','Avoid handwritten changes, unverified agents promising a new stamp, and assuming that a “one and the same person” affidavit is universally sufficient. Where the difference concerns a name used before or after marriage, the supporting civil record matters as much as the correction itself.'),('What varies','University correction procedures, identity record changes and acceptance by a foreign institution are separate decisions. Passport enquiries belong with DGIP; identity record enquiries belong with NADRA.'),('Name differences and Saudi-bound records','If your degree is being authenticated for use in Saudi Arabia, the same records are compared during the verification stage commonly called <a href="/guides/mosadaqa-degree-attestation/">mosadaqa</a>. Resolve the difference with the issuer before that stage begins, so you are not paying for a submission that will be queried.')],sources=['hec','dgip','nadra'],faqs=[('Can I correct the degree after attestation?','Correcting an academic record after authentication usually means the authenticated document no longer matches the corrected record, so the stages may need to be repeated. Ask the issuer and the receiving organisation before you start either process.'),('Which spelling should I change?','Change the record that is actually wrong, not the document that is easiest to alter. The issuer that holds the source record decides what its corrected version says.'),('Is a spelling difference always a problem?','Not always. Some receiving organisations accept a documented variation, a translation note or a supporting identity record. The organisation that will use the document decides what it accepts.')],related=['/problems/degree-passport-name-mismatch/','/documents/degree/','/services/hec-attestation/','/guides/mosadaqa-degree-attestation/']),
 dict(slug='mofa-attestation-pakistan',title='MOFA attestation: where to begin',category='Attestation essentials',summary='Start with the document category and the authority that comes before MOFA.',desc='Start with the document category and the authority that comes before the foreign affairs stage, then confirm the current instructions for your document.',answer='Identify your document and its prerequisite verification before choosing a submission route. Check MOFA’s current instructions for that category rather than using a single checklist for every document.',sections=[('What the MOFA stage means','Foreign affairs authentication is part of a wider document journey. It does not replace checking the original record or establishing acceptance by the receiving organisation.'),('A practical sequence','Identify the issuer, establish any preceding educational or other authority stage, confirm current MOFA requirements, then confirm what the recipient needs after authentication.'),('Documents to have available','The exact document title, issuing authority, existing verification and written destination requirements are useful starting information. The official checklist determines which originals and supporting records to submit. Where names differ across records, resolve the difference with the issuer first.'),('Common problems','Missing prerequisites, inconsistent identity details and using a submission route that is not permitted for the document can cause avoidable difficulties.'),('What varies','Official fees, permitted representation, appearance requirements, appointment arrangements and the destination route. Confirm these before travel or payment.')],sources=['mofa','hec','ibcc'],related=['/services/mofa-attestation/','/guides/apostille-vs-embassy-attestation/','/process/']),
 dict(slug='mosadaqa-degree-attestation',title='Mosadaqa degree attestation in Pakistan',category='Saudi Arabia',summary='What the term means, which stages apply and how name differences are resolved.',desc='Mosadaqa means attestation or verification of a document for Saudi use. See which records must match and how name differences are resolved.',answer='Mosadaqa means your document has been authenticated or verified for use in Saudi Arabia. For a degree, the file normally goes through the issuing institution and the educational authority first, then the foreign affairs stage, and finally whatever the Saudi side requires. If your degree, passport or CNIC details differ, resolve the difference with the issuer of the incorrect record before paying for attestation stages.',sections=[('What “mosadaqa” actually means','Mosadaqa (also written musadaqa or mosa daqa) is used in Pakistan for the attestation, authentication or verification of a document, and in practice it is used most often for degrees and certificates going to Saudi Arabia. It does not name one office that you visit. Your document still has to be checked by the institution that issued it and authenticated by the bodies competent for that document, and the Saudi side still decides what it accepts.'),('Mosadaqa, HEC and IBCC are not the same thing','<table class="content-table"><thead><tr><th>Term you will see</th><th>What it refers to</th><th>Who decides</th></tr></thead><tbody><tr><td>Mosadaqa / musadaqa</td><td>The authenticated or verified document a Saudi employer, university or authority asks for</td><td>Whichever authorities are competent for the document</td></tr><tr><td>HEC</td><td>Attestation service for eligible higher-education documents issued in Pakistan</td><td>HEC</td></tr><tr><td>IBCC</td><td>Attestation for relevant school-level qualifications and board-issued records</td><td>IBCC</td></tr><tr><td>Certificate verification (e-service)</td><td>Destination-side verification of an academic record</td><td>The authority receiving the submission</td></tr></tbody></table><p class="small">Read the table as a map of roles, not as a fixed sequence. Eligibility and the applicable stages depend on your qualification and its issuer.</p>'),('A practical sequence for a degree','<ol><li>Write down the exact qualification, awarding institution and campus.</li><li>Compare the name and date details across the degree, transcript, CNIC and passport.</li><li>Ask the issuer about any difference in the academic record before applying anywhere else.</li><li>Check the educational authority’s current eligibility and application instructions for your qualification.</li><li>Confirm the foreign affairs stage that applies to the document category.</li><li>Ask the Saudi organisation what it needs to receive: a verification submission, an authenticated original, or both.</li><li>Keep the recipient’s written wording with your file before you pay for any stage.</li></ol>'),('Name differences on the degree, passport and CNIC','<table class="content-table"><thead><tr><th>Where the difference is</th><th>Who can correct it</th><th>What to keep</th></tr></thead><tbody><tr><td>Name, father’s name or spelling on the degree or transcript</td><td>The university or board that issued the record</td><td>Your correction or verification request and the issuer’s written reply</td></tr><tr><td>Surname missing or added, or a name spelled differently on the passport</td><td>DGIP, through its passport service</td><td>Your passport application record</td></tr><tr><td>Name, father’s name or date of birth on the CNIC, B-form or identity record</td><td>NADRA</td><td>Your NADRA processing record</td></tr><tr><td>A name that changed after marriage or by registration</td><td>The authority that registered the change</td><td>The registration or name-change record</td></tr></tbody></table><p>A common case is a degree in a short form of the name while the passport and CNIC carry the full form, or a father’s name recorded differently on the degree. The comparison during verification is between the records you submit, so the correction has to be made on the record that is wrong.</p>'),('Where a name mismatch usually stops the process','A verification query commonly concerns the record details rather than the stamps: a surname missing on the degree, a different father’s name, a transliteration or spelling difference between the CNIC and the passport, or a changed name with no supporting record. The notice normally names the document and the discrepancy. Work from that wording, ask the issuer about correction or verification, and let the receiving authority confirm what evidence it will accept instead of buying another attestation stage first.'),('Special cases worth checking early','<ul><li>Degrees issued under an abbreviated or short name, with the full name on the CNIC and passport.</li><li>Father’s name differences where the passport and the degree were issued from different records.</li><li>Name changes after marriage, where the marriage registration record is the supporting evidence.</li><li>Qualifications from a renamed or merged institution, where the verification request names an institution that no longer exists under that title.</li><li>Documents where the date of birth differs between the academic record and the identity record.</li></ul>'),('Fees and timelines','This website does not publish fees or turnaround times. Official charges, appointment arrangements and processing times change, and they differ by document and by case. Confirm the current amount and the processing arrangement with the authority handling your stage before you pay anyone.'),('How we help with a Mosadaqa or verification query','We compare the records you hold, write out the exact difference, and prepare the questions to put to the issuer and to the receiving authority. We can sequence the stages so a correction happens before authentication rather than after it. We do not correct records, and we do not decide eligibility or acceptance.')],sources=['mosadaqa','saudi-moe','saudi','hec','nadra','dgip'],faqs=[('Is Mosadaqa an office I visit?','Mosadaqa describes the authenticated or verified document rather than a single office. The stages are handled through the issuing institution, the Pakistani educational authority and the Saudi-side verification or consular channel. The wording on your notice tells you where to follow up.'),('My degree name does not match my passport or CNIC. Can verification still proceed?','A difference between records is normally raised as a query that has to be resolved on the record that is wrong. The university corrects the academic record, DGIP the passport and NADRA the identity record. Ask the receiving authority what evidence it accepts for the difference.'),('Does a “one and the same person” affidavit solve a name difference?','Sometimes an organisation accepts a sworn declaration or a registered name-change record, and sometimes it requires the underlying record to be corrected. Ask the receiving authority in writing first and keep the answer with your file.'),('Do you issue Mosadaqa certificates or attestations?','No. SK Attestations is an independent assistance service. The competent authorities make the official decisions. We help compare records, prepare questions and sequence the stages for your document.'),('Can a Mosadaqa process be completed without the original degree?','That depends on the stage and the authority. Some submissions are electronic or verification-based, and others require the original document or an authenticated copy. Confirm the requirement for your document before sending originals anywhere.')],related=['/countries/saudi-arabia/','/problems/degree-passport-name-mismatch/','/problems/mosadaqa-verification-query/','/documents/degree/']),
 dict(slug='apostille-vs-embassy-attestation',title='Apostille or embassy legalization?',category='The right route',summary='The answer depends on more than a destination’s name.',desc='The applicable route depends on treaty status, the document and the recipient, not the destination name alone. Check the right question first.',answer='Establish whether the Apostille Convention applies to the document and between the relevant states. If it does not, ask the competent authorities about the applicable legalization route. Confirm the recipient’s instructions in either case.',sections=[('Two routes, one initial question','Start with who is receiving the document and why. A university, employer, court or public office may have additional requirements beyond authentication.'),('A practical sequence','Identify the country of issue and destination. Check the HCCH status table and relevant declarations. Ask the competent authority about the document’s scope. Obtain the receiving organisation’s written instructions.'),('Documents to have available','The document category, issuing country, destination and the recipient’s request. Check whether a translation, a copy or the original is requested.'),('Common problems','Country membership alone does not resolve treaty applicability. Entry-into-force dates, objections, document exclusions and the intended use may matter.'),('What varies','Translation, professional recognition, equivalence and destination-side procedures are separate questions. Do not treat a stamp as a guarantee that all of them are satisfied.')],sources=['hcch','mofa'],related=['/services/apostille/','/services/embassy-legalization/','/countries/']),
 dict(slug='hec-vs-ibcc',title='HEC or IBCC: which authority applies?',category='Education',summary='Look at the qualification and awarding body, not just the word “certificate”.',desc='Look at the qualification level and awarding body rather than the word “certificate” when you decide which educational authority to approach.',answer='HEC’s attestation service concerns eligible higher-education documents. For school-level qualifications, check IBCC’s scope and requirements. Technical qualifications and diplomas need a closer look at their issuer and level.',sections=[('Why the issuer matters','A university transcript, school certificate and vocational certificate can all describe education, but they are not interchangeable for attestation.'),('A practical sequence','Write down the exact qualification, awarding body and campus. Check the relevant authority’s scope. Identify prerequisites and only then select a submission route.'),('Documents to have available','Your qualification title, transcript or marks record, awarding institution and existing verification details. Use the authority’s current checklist for submission documents.'),('Common problems','Assuming every diploma goes through IBCC or every certificate goes through HEC can send a file to the wrong place.'),('What varies','Equivalence, recognition and attestation are distinct processes. A foreign qualification or technical certificate may need a different enquiry.')],sources=['hec','ibcc','navttc'],related=['/services/hec-attestation/','/services/ibcc-attestation/','/navttc/']),
 dict(slug='why-documents-get-rejected',title='Why was your document rejected?',category='Problem solving',summary='Use the stated reason to decide the next step.',desc='A query or rejection notice tells you which part of the file needs attention. Read the stated reason before you resubmit or pay again.',answer='Keep the rejection or query notice. Identify whether the issue concerns the record, missing supporting material, eligibility or submission method before attempting another application.',sections=[('Start with the actual notice','A rejection does not always mean the underlying document is invalid. Read the authority’s explanation and distinguish a request for information from a final decision.'),('A practical sequence','Save the notice and reference privately. Identify each requested change. Ask the responsible authority for clarification where needed. Resolve the issue through that authority before resubmitting.'),('Documents to have available','The query wording, document category and a list of what was submitted. Remove personal identifiers when describing the issue in an initial email.'),('Common problems','Resubmitting the same file without addressing the reason, changing the wrong record or buying an additional attestation that does not answer the query.'),('What varies','Review, correction, appeal and reapplication procedures belong to the deciding authority. Do not assume one authority’s procedure applies to another.')],sources=['hec','ibcc','mofa'],related=['/problems/document-rejected/','/problems/missing-document/','/contact/']),
]
DOCUMENTS = [
 dict(slug='education',title='Educational documents',desc='Degrees, diplomas, transcripts and certificates begin with the awarding body. Identify the qualification level before choosing an authority.',summary='Degrees, diplomas, transcripts and certificates each begin with the right issuer.',answer='Identify the qualification level and awarding body first. University, school and vocational records may follow different verification paths.',sections=[('Start with the qualification','Write down the document title, awarding institution and level. A diploma alone does not identify an attesting authority.'),('What to check together','Compare names, programme titles, dates and institution details across the certificate and supporting academic record.'),('Your next step','Check HEC for eligible higher-education records, IBCC for relevant school qualifications, or the competent vocational authority for technical records.')],sources=['hec','ibcc','navttc'],related=['/documents/degree/','/services/hec-attestation/','/services/ibcc-attestation/']),
 dict(slug='degree',title='University degree assistance',desc='A clear starting point for your degree, transcript and international plans, including the identity details that should match first.',summary='A clear starting point for your degree, transcript and international plans.',answer='Begin with the issuing university, the academic record and HEC’s current eligibility and application requirements. Confirm the receiving institution’s requirements separately.',sections=[('Check the record first','Compare your degree, transcript, CNIC and passport details. Ask the university about any difference in the academic record before proceeding.'),('Employment and study are different uses','An employer may request authentication, while a university or evaluation organisation may require records sent by a particular method. Obtain the recipient’s instructions. Saudi-bound academic verification is covered in our <a href="/guides/mosadaqa-degree-attestation/">mosadaqa guide</a>.'),('Before submission','Check the current official checklist and whether your qualification or institution needs a separate recognition or equivalence enquiry.')],sources=['hec','nadra'],related=['/services/hec-attestation/','/guides/degree-name-different-from-passport/','/guides/mosadaqa-degree-attestation/']),
 dict(slug='personal',title='Personal documents',desc='Guidance for birth, marriage, police and family records, and for checking that identity details agree across the documents you will submit.',summary='Guidance for birth, marriage, police and family records.',answer='The correct starting point depends on the exact record and who issued it. Civil registration, identity records and police certificates should not be treated as a single document category.',sections=[('Identify the precise document','Distinguish a marriage registration certificate from a marriage contract, a birth record from an identity document, and a police certificate from other character references.'),('Compare identity details','Check names and dates against the supporting records. Corrections must come through the responsible issuer.'),('Ask the recipient','Confirm the document format, any freshness requirement and whether translations or further authentication are requested.')],sources=['mofa','nadra'],related=['/documents/marriage-certificate/','/services/mofa-attestation/','/problems/name-mismatch/']),
 dict(slug='marriage-certificate',title='Marriage certificate assistance',desc='Identify the marriage record you actually hold and the requirements of the organisation receiving it, including translations and names.',summary='Identify the marriage record and the requirements of the organisation receiving it.',answer='Confirm exactly which marriage record is requested and which authority issued yours. A marriage contract, registration certificate and translation serve different purposes.',sections=[('Which record do you have?','Start with the document’s title and issuing body. Do not assume that a translation replaces the underlying record.'),('What to compare','Review both spouses’ names, identity details and the registration information. Ask the issuer about discrepancies.'),('Before international use','Obtain the recipient’s written instructions for originals, translations and authentication. The purpose may be family residence, marriage recognition or another process. Where a name changed at marriage, keep the registration record with the supporting identity documents.')],sources=['mofa','nadra'],related=['/documents/personal/','/services/embassy-legalization/','/problems/name-mismatch/']),
 dict(slug='business',title='Commercial and legal documents',desc='Understand the document, the signatory and the intended use before arranging authentication for commercial or legal instruments.',summary='Understand the document, signatory and intended use before arranging authentication.',answer='Identify whether the file is a corporate record, commercial instrument, agreement or power of attorney. Each can involve different issuing, witnessing and appearance requirements.',sections=[('Document and signatory','Record who issued or signed the instrument, their capacity and the organisation requesting it. Avoid sending confidential commercial terms in an initial enquiry.'),('Confirm the competent route','Ask the relevant authority whether a chamber, notary, registrar or other institution has a role. Do not assume these are interchangeable.'),('Powers of attorney','Execution, identity verification and personal appearance can be material. Obtain instructions from the competent authority and seek qualified legal advice on the instrument’s legal effect.')],sources=['mofa'],related=['/services/mofa-attestation/','/services/embassy-legalization/','/contact/']),
 dict(slug='international-use',title='Documents for international use',desc='Connect the document you have with the destination and purpose, and confirm whether verification, translation or authentication is required.',summary='Connect the document you have with the destination and purpose.',answer='Start with the organisation receiving your document. Authentication, translation and recognition are separate requirements, and not every document needs the same route.',sections=[('Ask for written requirements','Identify whether the recipient needs an original, certified copy, translation or direct verification from the issuer.'),('Establish the authentication route','Check Convention applicability for an apostille, or confirm the relevant embassy legalization route. Do not automatically purchase both.'),('Keep the purpose visible','Employment, study, immigration and business applications can use the same document in different ways. The purpose belongs in your assessment.')],sources=['hcch','mofa'],related=['/countries/','/services/apostille/','/guides/apostille-vs-embassy-attestation/']),
]
PROBLEMS = [
 dict(slug='name-mismatch',title='Name doesn’t match',tag='Passport ≠ Degree',desc='Passport, degree or identity record spelling differences: identify which issuer corrects which record before you pay for an attestation stage.',answer='Compare the actual records and identify the institution responsible for the difference. Do not change a document yourself.',guide='degree-name-different-from-passport',sections=[('Start with the comparison','Write down the name exactly as it appears on each document: degree, transcript, passport, CNIC or B-form. Note which field differs, not just that something differs.'),('Separate the records','An academic record, a passport and an identity record are held by different issuers. Only the issuer of the incorrect record can change it.'),('Ask before you pay','Ask the receiving organisation what evidence it accepts and whether the difference affects its decision. Do not buy an additional attestation stage to answer a question about a name.')]),
 dict(slug='degree-passport-name-mismatch',title='Degree, passport and CNIC name mismatch',tag='Three records, one name',desc='Degree, passport and CNIC names that differ: compare the records, identify the correct issuer and resolve the difference before attestation.',answer='A difference between the degree, passport and CNIC is resolved on the record that is wrong, not with an extra stamp: the university corrects the degree, DGIP the passport and NADRA the identity record. Ask the receiving organisation what evidence it accepts before spending on attestation stages.',guide='degree-name-different-from-passport',sections=[('What the three records are used for','<table class="content-table"><thead><tr><th>Record</th><th>What an authority compares it against</th></tr></thead><tbody><tr><td>Degree or transcript</td><td>The university’s own record of your qualification and name</td></tr><tr><td>Passport</td><td>The identity record and, in many processes, the name a document will be issued under</td></tr><tr><td>CNIC, B-form or identity record</td><td>The civilian identity record and the supporting family details it contains</td></tr></tbody></table>'),('The differences we see most often','<ul><li>A short or abbreviated name on the degree, with the full name on the CNIC and passport.</li><li>A surname present on the passport and missing from the degree.</li><li>A father’s name written differently on the degree and on the identity record.</li><li>Spellings that changed between two transliterations of the same name.</li><li>A name changed after marriage, without the registration record attached.</li><li>A date of birth that differs between the academic record and the identity record.</li></ul>'),('Which issuer you approach','<ol><li>Difference on the degree or transcript: ask the university or board that issued the record. Keep its written reply.</li><li>Difference on the passport: the passport service that issued it deals with the record.</li><li>Difference on the CNIC, B-form or family details: the national identity authority deals with the record.</li><li>Difference caused by marriage or a registered name change: the authority that registered the change.</li></ol><p>An affidavit or “one and the same person” declaration is sometimes accepted and sometimes not. Ask the receiving organisation in writing before relying on one.</p>'),('Order matters','Correcting a record after authentication usually means the authenticated document no longer matches the corrected record, and the stages may have to be repeated. Compare the records first, resolve the difference, and only then begin the authentication and legalization stages.'),('If the document is for Saudi Arabia','Academic records used in Saudi Arabia are compared during the verification stage commonly called <a href="/guides/mosadaqa-degree-attestation/">mosadaqa</a>. The same records are checked there, so the difference has to be resolved at source rather than explained later.'),('What we can and cannot do','We can list the exact differences, prepare the questions for each issuer, and sequence the correction and authentication stages. We do not alter documents, influence a decision, or guarantee that a receiving organisation will accept a particular explanation.')]),
 dict(slug='document-rejected',title='Document rejected',tag='Something is missing',desc='Use the authority’s stated reason as the starting point, and distinguish a request for information from a final decision before resubmitting.',answer='Use the authority’s stated reason as the starting point. Repeating a submission without addressing the query may not resolve it.',guide='why-documents-get-rejected',sections=[('Read the notice twice','Distinguish a request for further information from a refusal on eligibility. They lead to different next steps, and one of them may not need a new application at all.'),('Match the reason to the right issuer','A query about the underlying record belongs with the issuer. A query about the submission belongs with the authority that received it. Sending both to the wrong place wastes a cycle.'),('Prepare the reply before paying again','List what has changed since the first submission. If nothing has changed, ask the authority what it needs rather than repeating the same file with an extra stamp.')]),
 dict(slug='previously-rejected',title='Previously rejected',tag='Understand before resubmitting',desc='Reworking a file that was rejected earlier: what to review, what to change and what to confirm before a second submission.',answer='A previous rejection needs a review of the reason and what has changed. Additional stamps alone may not address the issue.',guide='why-documents-get-rejected',sections=[('Establish what has actually changed','Write down each point of the earlier query and what you have done about it. An unchanged file submitted again usually produces the same result.'),('Decide whether a correction or a clarification is needed','Some queries are answered with a corrected record, others with a document the issuer sends directly, and others with a written clarification from the authority that raised them.'),('Keep one private summary of the file','A short private summary of documents, stages, dates and reference numbers makes a second submission easier to prepare and easier to explain. Do not include identity numbers in an initial email to a new adviser.')]),
 dict(slug='which-authority',title='Not sure which authority',tag='HEC? IBCC? MOFA?',desc='Which authority to approach first depends on the qualification level, the awarding body and the intended use rather than the document title alone.',answer='The document’s issuer and qualification level determine which authority to check first. The name of the document alone may be insufficient.',guide='hec-vs-ibcc',sections=[('Identify the awarding body','Write down the institution or board that awarded the qualification and the level of the award. This decides the first enquiry.'),('Separate the stages','Verification of the original record, educational attestation, foreign affairs authentication and destination-side checks are different stages with different officeholders.'),('Confirm with the issuer of the requirement','Ask the organisation that asked for the document what it actually needs: verification, an authenticated original, an equivalence decision or a combination.')]),
 dict(slug='apostille-or-embassy',title='Apostille or embassy?',tag='Which route applies?',desc='Treaty status, the document category and the recipient’s instructions decide whether an apostille or a consular route applies to your file.',answer='Check treaty applicability and the receiving organisation’s instructions before choosing an authentication route.',guide='apostille-vs-embassy-attestation',sections=[('Treaty status is document-specific','Membership of the Convention does not by itself decide the route. Entry into force, declarations and the type of document can all matter.'),('The recipient still decides','A destination-side authority may require its own legalization stage or an internal procedure after authentication. Ask for its written instructions.'),('Do not buy both routes','If the applicable route is unclear, ask the competent authority before paying for two sets of stamps. An unnecessary stage usually delays rather than helps.')]),
 dict(slug='missing-document',title='Missing document',tag='What do you need first?',desc='Work out whether the missing item is an original record, supporting evidence or an earlier verification, and ask about replacement records.',answer='Find out whether the missing item is an original record, supporting evidence or an earlier verification. These need different next steps.',guide='why-documents-get-rejected',sections=[('Classify the missing item','An original certificate, a supporting identity record and an earlier verification certificate are obtained from different places, and often on different timelines.'),('Ask about replacement records','An issuer may be able to reissue or verify a lost record. Ask what the process is and whether it issues the record directly to the requesting authority.'),('Confirm what the recipient will accept','Before ordering a replacement, confirm whether the receiving organisation requires the original, a certified copy or direct verification.')]),
 dict(slug='mosadaqa-verification-query',title='Mosadaqa verification query',tag='Degree queried for Saudi use',desc='A Mosadaqa or certificate-verification query about a degree: what it usually concerns, what to prepare and who to ask before resubmitting.',answer='A verification query usually concerns the record details or the document itself rather than the stamps. Read the exact wording, resolve the issue at the issuing institution, and let the receiving authority confirm what it will accept.',guide='mosadaqa-degree-attestation',sections=[('What the query usually concerns','<ul><li>A name, father’s name or date of birth that differs between the degree and the identity records submitted.</li><li>An institution, programme title or year that the awarding body records differently.</li><li>A document that is illegible, altered-looking or missing a page.</li><li>An unclear submission: the wrong document uploaded, or a verification step still pending.</li></ul><p>The exact wording decides the next step. Work from the notice rather than from a general checklist.'),('Prepare the comparison before you reply','Put the degree, transcript, CNIC, passport and the notice side by side. Write out each difference and the record that carries it. This is what both the issuer and the receiving authority will ask about.'),('Who to ask','The awarding institution answers questions about its own record. The identity authority answers questions about the CNIC or B-form. The authority that raised the query answers questions about what it will accept next. Ask each in writing and keep the replies with your file.'),('What we help with','We prepare the comparison, draft the questions for each office, and set the order of the correction and verification steps so a query is not answered with an unnecessary extra attestation. We do not alter records or decide the outcome.')]),
]
COUNTRIES = {
 'UAE': 'For use in the UAE, establish what the receiving organisation needs and check UAE MOFA’s attestation instructions. Ask about any destination-side stage and translations before choosing a route.',
 'Saudi Arabia': 'For Saudi Arabia, ask the requesting organisation whether the requirement is academic verification (often called mosadaqa), employment attestation or a trade-skills check. The stages differ, so keep the exact wording of the request and confirm whether an online verification submission, an authenticated original or both are expected.',
 'Qatar': 'For Qatar, obtain the requesting organisation’s checklist and confirm the competent consular route. The document category, purpose and any translation request matter.',
 'Oman': 'For Oman, check Convention applicability as well as the recipient’s requirements. An authentication route does not settle recognition or translation requirements.',
 'Bahrain': 'For Bahrain, check the relevant treaty relationship and the document’s scope. Confirm with the receiving institution before arranging additional legalization.',
 'Kuwait': 'For Kuwait, ask the relevant embassy and recipient about the applicable authentication stages. Check whether the request is for the original, a copy or a translation.',
 'UK': 'For the UK, establish whether the recipient needs authentication, direct issuer verification or a different form of evidence. Confirm Convention applicability where an apostille is requested.',
 'Germany': 'For Germany, review relevant Convention declarations and the German recipient’s instructions. Confirm translation and recognition requirements separately.',
 'France': 'For France, ask the recipient which form of the document it accepts and whether a translation is needed. Verify the applicable authentication route before submission.',
 'Italy': 'For Italy, establish whether the request concerns document authentication, academic recognition or both. Confirm the receiving institution’s requirements for translations.',
 'Canada': 'For Canada, distinguish an apostille request from credential evaluation or direct academic verification. Check the particular receiving organisation’s instructions.',
 'Australia': 'For Australia, ask whether the recipient needs an original, certified copy or issuer verification. Authentication and professional or academic recognition are separate checks.',
 'USA': 'For the USA, identify the specific receiving institution and its document rules. An employer, university and licensing board may ask for different evidence.',
 'Europe': 'Europe is not a single document jurisdiction. Identify the specific country and receiving organisation before checking the authentication route.',
 'Other': 'Start with the exact destination country and receiving organisation. We can help identify which official instructions to check for your document and purpose.'
}
FAQS = [
 ('Government','Are you a government authority?','No. SK Attestations provides independent private assistance. HEC, IBCC, MOFA, embassies and other competent authorities make their own official decisions.'),
 ('Government','Can you guarantee an attestation?','No. Eligibility, approval and acceptance belong to the relevant authorities and receiving organisations. We can help you understand and prepare for the process.'),
 ('Documents','Can someone submit on my behalf?','Representation, personal appearance and courier rules vary by authority and document. Check the current official instructions before authorising anyone or sending originals.'),
 ('Documents','Should I upload my documents here?','No. This website has no document upload. Start with the document type, destination, purpose and a description of the issue. Do not send identity numbers or scans in the initial enquiry.'),
 ('Apostille','Does an apostille work for every country?','No. Check the Convention relationship, document scope and relevant declarations, as well as the receiving organisation’s requirements. Country membership alone is not a complete assessment.'),
 ('Embassy','Do I need both an apostille and embassy legalization?','Do not assume both are needed. Establish which route applies to the specific document and purpose, and confirm it with the competent authority.'),
 ('Mosadaqa','What does “mosadaqa” mean?','Mosadaqa is used in Pakistan to mean the attestation, authentication or verification of a document, and most often a degree or certificate intended for use in Saudi Arabia. It is not a separate office: the document still has to be checked by its issuer and authenticated by the authorities competent for that document.'),
 ('Mosadaqa','Is mosadaqa the same as HEC attestation?','No. HEC is one stage for eligible higher-education documents issued in Pakistan, and mosadaqa describes the authenticated or verified outcome the Saudi side expects. Which stages apply depends on your qualification, its issuer and the organisation receiving the document.'),
 ('Problems','What if my degree and passport names differ?','Compare the records and contact the responsible issuer about correction or verification. Do not physically alter the document or assume an affidavit will be accepted.'),
 ('Problems','My degree, passport and CNIC names all differ. Where do I start?','Compare the three records and write down the exact difference. Only the issuer of the incorrect record can change it: the university for the degree, DGIP for the passport and NADRA for the identity record. Resolve the difference before paying for attestation stages.'),
 ('Problems','Is an affidavit enough for a name difference?','Do not assume so. Some organisations accept a sworn declaration or a registered name-change record, and others require the underlying record to be corrected. Ask the receiving organisation and the issuer in writing before paying for another stage.'),
 ('Countries','Are requirements the same for every destination?','No. They vary by destination, receiving organisation, document and purpose. Obtain written instructions from the organisation that will use the document.'),
 ('NAVTTC','Do you conduct NAVTTC tests?','No. We provide independent test booking and technical document guidance. Official centres and programme authorities control eligibility, testing, availability and outcomes.'),
]
